  'employment.modality.question': 'Zure kontratu mota',
  'employment.modality.help':
    'Kontratuaren izenburuak edo lehen klausulak adierazten du. Zure nominetan gako bat ageri bada (100, 402, 410…), hark ere laguntzen du ezagutzen.',
  'employment.modality.kind': 'Zer kontratu mota da?',
  'employment.modality.permanent_hint': 'Amaiera-datarik gabe. 100 edo 200 gakoa.',
