    'IRAV ({mes}): {irav}; IPC: {ipc}. Hilabete bakoitza 2024ko azarotik aurrera, argitaratu zen egunarekin eta INErako estekarekin.',
  'rent_indices.h1': 'Hilabete bakoitzeko IRAV eta IPC',
  'rent_indices.lead':
    'Zure alokairua urtero zenbat igo daitekeen markatzen duten indizeak, INEk zifra bakoitza argitaratu zuen egunarekin. IRAV hilero ateratzen da, behin betiko IPCarekin batera.',
