  'rent_indices.cell_pending': 'Zain',
  'rent_indices.note_flash':
    'IPC aurreratua INEk hilabete bakoitzaren amaieran ematen duen estimazio bat da; behin betikoa bi aste inguru geroago iristen da, eta batzuetan hamarren bat aldatzen da. IRAVek ez du aurreraturik.',
  'rent_indices.note_igc':
    'INEk IGC bere formulatik ateratzen den bezala argitaratzen du, eta askotan negatiboa da. Prezio bat harekin berrikusteko, Ley 2/2015 arauak {min} eta {max} artean uzten du: negatiboa bada, berrikuspena {min} da, eta {max} gainditzen badu, {max} hartzen da.',
  'rent_indices.caps_title': 'Zenbat igo daitekeen zure alokairua urtero',
  'rent_indices.caps_lead':
    'Zure kontratua 2015eko apirilaren 1ekoa edo geroagokoa bada, zure alokairua kontratuak hala dioenean bakarrik igo daiteke, eta urtean behin: kontratuaren urte bakoitza betetzen den egunean. Kontratuak itundutako indizearen arabera igotzen da, une horretako legezko muga gainditu gabe. Hauek dira etxebizitza-kontratuen mugak 2019ko martxoaren 6tik aurrera:',
  'rent_indices.cap.ipc.when': '06-03-2019tik 30-03-2022ra',
  'rent_indices.cap.ipc.rule': 'IPC.',
  'rent_indices.cap.igc.when': '31-03-2022tik 31-12-2023ra',
  'rent_indices.cap.igc.rule':
    'IGC (gehienez 2\u00a0%), edo IPC, txikiagoa bada. Itun berri batek IGC beste igoera batengatik alda zezakeen. Zure jabea etxebizitza-edukitzaile handia bada (bizitegi-erabilerako hamar higiezin baino gehiago edo bizitegi-erabilerako 1.500 m² baino gehiago), igoerak ezin du IGC gainditu, beste igoera bat itundu bazenuten ere.',
  'rent_indices.cap.three.when': '2024an',
  'rent_indices.cap.three.rule':
    '3\u00a0%, edo IPC, txikiagoa bada. Itun berri batek 3\u00a0% hori beste igoera batengatik alda zezakeen. Zure jabea etxebizitza-edukitzaile handia bada, igoerak ezin du 3\u00a0% gainditu, beste igoera bat itundu bazenuten ere. 26-05-2023tik aurrera, etxebizitza-edukitzaile handia da bizitegi-erabilerako hamar higiezin baino gehiago edo bizitegi-erabilerako 1.500 m² baino gehiago dituena, eta bizitegi-merkatu tentsionatuko eremu deklaratu batean autonomia-erkidegoak muga hori jaits dezake, eremu horretan bizitegi-erabilerako bost higiezin edo gehiagora.',
  'rent_indices.cap.irav.when': '01-01-2025etik aurrera',
  'rent_indices.cap.irav.when_until': '01-01-2025etik {hasta} datara',
  'rent_indices.cap.irav.rule':
    '26-05-2023tik aurrerako kontratuetan, IRAV edo IPC, txikiena; aurrekoetan, IPC.',
  'rent_indices.cap.two.when': '{desde} datatik aurrera',
  'rent_indices.cap.two.rule':
    'IRAV kontratu guztietan. Eta 31-12-2027ra arte, itun berririk gabe, gehienez 2\u00a0%. Eta zure errentak erreferentziako indizeen sistemaren arabera aplika dakiokeen prezio-muga gainditzen badu, ezin da inolako igoerarik egin.',
  'rent_indices.large_landlord_source':
    'art. 3.k (Ley 12/2023, de 24 de mayo, por el derecho a la vivienda)',
  'rent_indices.reference_index':
    'Sistema Estatal de Referencia del Precio del Alquiler de Vivienda (Ministerio de Vivienda)',
  'rent_indices.status.pending_validation':
    'Egoera {fecha} datan: {norma} araua {desde} datatik aurrera dago indarrean, eta baliozkotzeko zain dago. Kongresuak promulgazioaren ondorengo 30 egunetan bozkatu behar du; baliozkotzen ez badu, indargabetuta geratzen da.',
  'rent_indices.status.in_force':
    'Egoera {fecha} datan: Kongresuak {norma} araua baliozkotu zuen; akordioa {estado} datan argitaratu zen.',
  'rent_indices.status.repealed':
    'Egoera {fecha} datan: Kongresuak {norma} araua indargabetu zuen; akordioa {estado} datan argitaratu zen. Haren muga (2\u00a0%) ez da aplikatzen jada.',
  'rent_indices.status_short.pending_validation': 'Kongresuak baliozkotzeko zain',
  'rent_indices.status_short.in_force': 'Kongresuak baliozkotua',
  'rent_indices.status_short.repealed': 'Kongresuak indargabetua',
  'rent_indices.now':
    'Azken IRAVarekin ({irav}) eta {norma} araua indarrean dagoen bitartean, itun berririk gabeko muga hau da: {tope}, bien artean txikiena. Eta zure errentak erreferentziako indizeen sistemaren arabera aplika dakiokeen prezio-muga gainditzen badu, ezin da inolako igoerarik egin.',
  'rent_indices.repealed':
    'Muga bera (2\u00a0%) zuten eta Kongresuak indargabetu zituen dekretuak: {lista}. Egun haietako igoera bat kasu zalantzagarria da.',
  'rent_indices.repealed_item': '{norma} araua, {periodo} indarrean egon zena',
