  'bills.result.compare_text':
    'Berrikuspen honek ez ditu eskaintzak alderatzen. CNMCk alderatzaile ofizial bat du, merkaturatzaileek bidaltzen dizkioten eskaintzekin; zure fakturak hara eramaten duen QR kode bat dakar.',
