  'bills.result.restart': 'Hasi berriro',
  'bills.documents.consent':
    'Nire baimen esplizitua ematen dut AA eredu batek dokumentu hauek irakur ditzan eta formularioa bete dezan. Badakit datu pertsonalak izan ditzaketela, hala nola izenak, helbideak edo kontu-zenbakiak. Hornidura-kodetik (CUPS) aztarna bat bakarrik geratzen da, errepikatutako faktura bat antzemateko. Europar Batasunean irakurtzen dira, eta ez dira gordetzen.',
  'bills.electricity.documents.start_help':
    'Zure argiaren fakturak igo ditzakezu, haietan irakurtzen denarekin datuak betetzeko, edo zuk idatz ditzakezu. Ezer berrikusi aurretik, datu bakoitza berresten duzu, fakturaz faktura.',
  'bills.electricity.documents.upload': 'Igo argiaren faktura bat edo gehiago',
  'bills.electricity.documents.files_hint':
    'Zure argiaren fakturen orrialde guztiak eta, badituzu, kontratua edo prezio-aldaketaren abisu bat, edozein ordenatan. Gehienez 25 argazki edo PDF orrialde, guztira. Argazkiak eta PDFen orrialdeak irudi bihurtzen dira zure gailuan, bidali aurretik.',
  'bills.telecom.documents.start_help':
    'Zure kontratua eta zure telefonoaren edo interneten fakturak igo ditzakezu, haietan irakurtzen denarekin datuak betetzeko, edo zuk idatz ditzakezu. Ezer berrikusi aurretik, datu bakoitza berresten duzu.',
  'bills.telecom.documents.upload':
    'Igo zure kontratua eta, badituzu, zure telefonoaren edo interneten fakturak',
  'bills.telecom.documents.files_hint':
    'Kontratua edo haren iraupen-konpromisoaren baldintzak eta, badituzu, zure fakturak: penalizaziokoak edo bajaren ondorengoak, eta kobrantzak aztertu nahi dituzun beste edozein faktura, edozein ordenatan. Gehienez 25 argazki edo PDF orrialde, guztira. Argazkiak eta PDFen orrialdeak irudi bihurtzen dira zure gailuan, bidali aurretik.',
  'bills.pass.title': 'Zure fakturen txostena eta gutuna',
  'bills.pass.letter_note':
    'Gutuna txantiloi bat da. Zure gailuan deskargatzen da, eta ez da hemendik bidaltzen: erabili ala ez, eta nola, zure erabakia da.',
