    'Datu hauek gutuna zure gailuan betetzeko bakarrik erabiltzen dira; ez dira bidaltzen, ezta gordetzen ere.',
  'bills.telecom.charges.title': 'Kobratzen dizutena',
  'bills.telecom.charges.lead':
    'Zure fakturetan irakurritako lerro bakoitza, kobratzen dizuten guztia ezagut dezazun. Zuk kontratatu ez duzun zerbait ikusten baduzu, galdetu zure konpainiari.',
  'bills.telecom.charges.extras':
    '«Extra» marka duten lerroak tarifikazio gehigarrikoak edo hirugarrenen zerbitzuetakoak dira: zure tarifaz aparte kobratzen dira. Zuk kontratatu ez baduzu, galdetu zure konpainiari.',
  'bills.telecom.charges.fees':
    'Fakturak ez du esaten kuotetatik zein den zure tarifarena: egiaztatu kuota bakoitza ezagutzen duzula.',
  'bills.telecom.charges.promotions': 'Amaitzen diren deskontuak',
  'bills.telecom.charges.rights': 'Arauak dioena',
  'bills.telecom.charges.disconnect':
    'Zure konpainiari eska diezaiokezu tarifikazio gehigarriko zerbitzuak eta nazioarteko deiak deskonektatzeko. Idatziz, telefonoz edo internet bidez egindako eskaera onartu behar du, eta gehienez 10 egunean deskonektatu; epe horretan egiten ez badu zuri egotzi ezin zaizun arrazoi batengatik, zerbitzu horiek kostatzen dutena haren kontura doa.',
  'bills.telecom.charges.unrequested':
    'Zerbitzu bat eskatu ez baduzu, legeak ez du onartzen hura kobratzea, eta zerbitzua ematen dizunari ez erantzutea ez da onartzetzat hartzen. Zuk kontratatu ez baduzu, galdetu zure konpainiari.',
  'bills.telecom.pass.title': 'Txostena eta gutunak',
  'bills.telecom.pass.letter_note':
    'Gutunak txantiloiak dira. Zure gailuan deskargatzen dira, eta ez dira hemendik bidaltzen: erabili ala ez, eta nola, zure erabakia da.',
  'bills.telecom.pass.download_exit_letter':
    'Deskargatu baldintza-aldaketa baten ondorengo bajari buruzko gutuna (PDF, doan)',
  'bills.telecom.pass.download_penalty_letter':
    'Deskargatu penalizazioa berrikusteko eskatzen duen gutuna (PDF)',
  'bills.telecom.letters.title': 'Doan deskarga dezakezun gutuna',
  'bills.telecom.letters.text':
    'Gutun honek zure operadoreari esaten dio noiz abisatu zizun aldaketaz eta noiz eskatu zenuen baja, zifrarik gabe, eta doan deskargatzen da. Zure gailuan sortzen da.',
  'bills.telecom.letter.legend': 'Gutunetarako zure datuak (aukerakoa)',
  'bills.telecom.letter.company': 'Operadorea',
  'bills.telecom.letter.reference': 'Bezero- edo kontratu-zenbakia',
  'bills.telecom.letter.privacy':
    'Datu hauek gutunak zure gailuan betetzeko bakarrik erabiltzen dira; ez dira bidaltzen, ezta gordetzen ere.',
  'bills.pass.price':
    '4,99 €, IVA barne. Ordainketa bakarra, konturik eta harpidetzarik gabe. Paseak 7 egun irauten du, eta nabigatzaile honetan bakarrik balio du: denbora horretan gehienez 15 dokumentu-sorta irakur ditzakezu, edozein ataletan, eta txostena berriro deskargatu, berriz ordaindu gabe. Beste gailu batean, leiho pribatu batean edo nabigazio-datuak ezabatzen badituzu, galdu egiten da.',
  'bills.basket.memory':
    'Ez dugu ezer gordetzen: zure urtea fitxa honetan bakarrik bizi da. Ixten edo berriro kargatzen baduzu, igo berriro zure fakturak. Ordaintzen baduzu, berrikusi dituzun fakturak fitxa honetan geratzen dira zain ordainketa-orrian zauden bitartean, eta guztiak itzultzen dira zurekin; irakurri bai baina oraindik berrikusi ez dituzunak, ez.',
