  'client.bills.electricity.report.intro':
    'Txosten honek berrikusi zenuen argiaren faktura bakoitza zure prezioekin eta arauak finkatzen duenarekin alderatzen du, berretsi zenituen datuekin. Faktura bakoitza behin bakarrik zenbatzen da, gutxiegi kobratutakoa aparte doa, eta urtebeterako estimazioa ez zaio inolako guztizkori batzen. Arauari buruzko informazioa ematen du, eta ez da aholkularitza juridikoa.',
