    '16-06-2019tik aurrera, legeak ez du onartzen irekiera-komisioak dagoeneko estaltzen dituen zerbitzuengatik aparte kobratzea, hala nola azterketa edo izapideak (art. 14.4).',
  'client.mortgage.calculation.flags.opening_fee_case_law':
    'Irekiera-komisioari buruz, Tribunal de Justicia de la Unión Europea auzitegiak dio epaileak kasuz kasu aztertzen duela argi azaldu zen ala ez; epaile baten araberakoa da.',
  'client.mortgage.calculation.flags.insurance_tied':
    'Legeak arautzen du noiz eska diezazukeen bankuak asegurua edo beste produktu bat mailegua emateko, eta aseguru hori beste erakunde batekin kontratatzeko aukera ematen dizu (art. 17).',
  'client.mortgage.calculation.flags.insurance_before_lcci':
    'Zure eskritura 16-06-2019 baino lehenagokoa da, eta egun horretan hasi zen legea salmenta lotuak debekatzen (art. 17). 2012tik aurrera, Orden EHA/2899/2011 aginduak lotutako zerbitzu bakoitza bereiz kontrata zitekeen eta zer baldintzatan jakinaraztera behartzen zuen (art. 12): hemen ez da baloratzen.',
  'client.mortgage.calculation.information.fein_timing':
    '16-06-2019tik aurrera, bankuak Europako informazio normalizatuaren fitxa (FEIN) eta abisuen fitxa (FiAE) ematen dizkizu, eskritura baino gutxienez 10 egun natural lehenago (arts. 14 eta 15).',
  'client.mortgage.calculation.information.transparency_act':
    'Beranduenez eskrituraren aurreko egunean, notarioak aholkularitza ematen dizu eta kobratzen ez zaizun akta batean jasotzen du, eta eskriturak hori aipatzen du (art. 15).',
  'client.mortgage.calculation.information.handwritten_statement':
    '15-05-2013tik 15-06-2019ra bitartean, hipoteka pertsona fisiko gisa eskatu bazenuen, etxebizitza baten gainean edo lur bat edo eraikin bat erosteko edo kontserbatzeko, eta tasaren aldakuntzarako mugak bazituen, zorua eta sabaia adibidez, «en los cuales el límite de variabilidad a la baja sea inferior al límite de variabilidad al alza», interes-tasaren arriskua estaltzeko tresna bat bazuen edo dibisetan ematen bazen, eskriturak eskuz idatzitako adierazpen bat eraman behar zuen, haren arriskuez ohartarazi zintuztela jasotzen zuena (Ley 1/2013, art. 6).',
  'client.mortgage.calculation.information.limitation_rule':
    'Tribunal de Justicia de la Unión Europea auzitegiaren arabera, gastuen klausula baten ondorioz ordaindutakoa eskatzeko epea ezin da hasi ordainketaren egunean zenbatzen, baizik eta klausula baliozkoa ez zela jakin zitekeenean. Araua da, ez zure kasuaren kalkulu bat.',
  'client.mortgage.calculation.information.prior_step_439bis':
    '03-04-2025etik aurrera, legeak aurretiazko pauso zehatz bat arautzen du hipoteka baten klausulengatik epaitegi batera jo aurretik (Ley de Enjuiciamiento Civil, art. 439 bis). Estekan duzu legearen testua.',
  'client.mortgage.calculation.information.loan_assignment':
    '08-10-2026tik aurrera, Real Decreto-ley 29/2026 arauak art. 25 bis gehitzen dio legeari: bankuak zure mailegua beste bati lagatzen badio, bankuari aurka zenezakeena titular berriaren aurrean ere gordetzen duzu, eta lagapenaren berri eman behar zaizu, salbu eta bankuak, titular berriarekin ados, maileguaren zerbitzuak ematen jarraitzen badu (art. 25 bis.3). Baliozkotzeko zain dago.',
  'client.mortgage.calculation.information.complaints_service':
    'Banco de España erakundearen Servicio de Reclamaciones zerbitzuak bankuei buruzko kontsultak eta kexak artatzen ditu (Ley 44/2002, art. 30), eta kontsumoko bulego publikoek doan informatzen dute.',
