    '{fecha} datan, epea baino lehen kapital hau itzuli nuen: {capital}; eta aurretiazko itzulketa horren konpentsazio gisa, zenbateko hau kobratu zenidaten: {cobrado}. Kredituaren adostutako amaiera {fin} zen.',
