  'client.household.calculation.dismissal.none_of_the_two':
    'Idazkia egon zen, eta kalte-ordaina zure eskura jarri zen: bi arrazoi horiengatik, arauak ez du kaleratzea presumitzen.',
  'client.household.calculation.dismissal.none_of_the_two_no_severance_due':
    'Idazkia egon zen eta, urte osatugabea zenbatzeko modu honekin, ez zegokizun kalte-ordainik: ez zen falta zure eskura jartzea, eta arauak ez du kaleratzea presumitzen.',
  'client.household.calculation.dismissal.short_notice':
    'Aurreabisu laburragoak ez du presuntzio hori ekartzen, baina aldea ordaindu behar dizute.',
  'client.household.calculation.dismissal.figure_difference':
    'Kalte-ordainaren zenbatekoan akats barkagarri batek ez du presuntzio hori ekartzen, baina aldea ordaindu behar dizute; zenbatekoa askoz txikiagoa balitz, beste modu batean balora liteke.',
  'client.household.calculation.night.notice_time':
    'Harremanaren amaiera ordu honetan jakinarazi zizuten: {time}.',
  'client.household.calculation.night.on_the_hour':
    'Etxean bizi denaren kasuan, amaitzeko erabakia ezin da gauzatu 17:00 eta 08:00 artean; berrikuspenak abisuaren orduaren arabera begiratzen du. 17:00etan edo 08:00etan zehazki, ez dago argi ordu hori barruan dagoen, eta ez da zenbatzen.',
  'client.household.calculation.night.serious_breach_alleged':
    '17:00 eta 08:00 artean, amaiera leialtasun- eta konfiantza-betebeharren hutsegite oso larri baten ondorio bada bakarrik egin daiteke; berrikuspen honek ez du baloratzen hutsegiterik izan zen.',
  'client.household.calculation.night.inside':
    'Etxean bizi denaren kasuan, amaitzeko erabakia ezin da gauzatu 17:00 eta 08:00 artean, leialtasun- eta konfiantza-betebeharren hutsegite oso larria izan ezean; berrikuspenak jakinarazi zizuten orduaren arabera begiratzen du.',
  'client.household.calculation.severance.figure':
    'Kalte-ordaina: zerbitzu-urte bakoitzeko 12 eguneko soldata. {days} egun dira, egunean {daily}: {amount}.',
  'client.household.calculation.severance.capped':
    'Kalte-ordainak {months} hileko soldatako muga du: {amount} geratzen da.',
  'client.household.calculation.severance.not_made_available':
    'Ez zen zure eskura jarri amaiera jakinarazi zizuten unean bertan: osorik ordaindu behar dizute.',
  'client.household.calculation.severance.shortfall':
    'Zure eskura jarritakoa: {offered}. Falta dena: {difference}.',
  'client.household.calculation.severance.offered_unknown':
    'Ez dago jasota zer zenbateko jarri zen zure eskura.',
  'client.household.calculation.severance.salary_unknown':
    'Diruzko soldatarik gabe, ezin da kalte-ordaina kalkulatu.',
  'client.household.calculation.severance.prorated_note':
    'Kalkulu honek hasitako hilabete bakoitzeko egun bat zenbatzen du, eta hori da atera litekeen gehienekoa. Arauak ez du esaten urte osatugabe bat nola zenbatu; horregatik, guztizkoak urte beteen kalkulua bakarrik hartzen du kontuan, ez hau.',
  'client.household.calculation.notice.days':
    'Aurreabisua: {required} egun natural, abisuaren hurrengo egunetik aurrera zenbatuta. Emandakoak: {given}. Falta direnak: {missing}.',
  'client.household.calculation.notice.salary_unknown':
    'Diruzko soldatarik gabe, ezin da euroetan baloratu aurreabisutik falta dena.',
  'client.household.calculation.notice.substitute':
    'Falta diren {missing} egunen ordez, haien soldata ordain daiteke: egunean {daily}, {amount}.',
  'client.household.calculation.notice.substitute_paid':
    'Ordaindu zizutena: {paid}. Egun horiek estaltzen ditu.',
  'client.household.calculation.notice.substitute_short':
    'Ordaindu zizutena: {paid}. Falta dena: {difference}.',
  'client.household.calculation.notice.leave':
    'Aurreabisuan, lanaldi osoan lan egiten duenari astean {hours} ordu ordaindu ematen dizkio arauak lana bilatzeko.',
  'client.household.calculation.unemployment.situation':
    '11.2 artikuluko atzera egitea legezko langabezia-egoera da: langabezia-prestazioa eska zenezake.',
  'client.household.calculation.unemployment.general_rules':
    '2022ko urriaren 1etik aurrera, langabeziagatik kotizatzen da, eta arau orokorrak aplikatzen dira: azken sei urteetan 360 egun kotizatuta (art. 266.b LGSS), beste prestazio baterako erabili ez dituzunak (art. 269.2 LGSS), eta prestazioa 70 % da lehenik eta 60 % gero. Berrikuspen honek ez du prestazioa kalkulatzen.',
  'household.title': 'Etxeko langilea: berrikusi zure soldata eta atzera egitea legearen aurrean',
  'household.description':
    'Egiaztatu etxe bateko zure lanaren soldata, lanaldia, oporrak, kitapena eta familiaren atzera egitea (desistimiento) legearen aurrean, zifraz zifra eta bakoitza bere artikuluarekin.',
  'household.h1': 'Egiaztatu etxean ordaintzen dizutena bidezkoa den',
  'household.lead':
    'Etxe batean egiten duzu lan: jarri zure soldata, zure lanaldia eta, amaitu bada, nola amaitu zen, legeak ezartzen duenaren ondoan. Zifra bakoitzak zer artikulutatik ateratzen den adierazten du.',
  'household.beta': 'Beta',
  'household.beta_note':
    'Probetan dagoen atala. Familiarekin itundu duzunak legeak dioena hobe dezake: horren araberakoa dena beti adierazten da.',
  'household.no_js':
    'Berrikuspenak JavaScript behar du. Osorik zure gailuan egiten da, eta idazten duzuna ez da handik ateratzen.',
